# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 13)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_half_step_rounds_up(self):
        spans = [Span(75, 180)]
        self.assertEqual(
            round_labels(spans, 30),
            ["01:30-03:00 (1h 30m)"]
        )

    def test_several_spans(self):
        spans = [Span(0, 60), Span(480, 540)]
        self.assertEqual(
            round_labels(spans, 30),
            ["00:00-01:00 (1h 0m)", "08:00-09:00 (1h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
